export function checkout(items, inventory, discountPercent, customer) {
  if (!Array.isArray(items) || !Array.isArray(inventory)) {
    throw new TypeError("Items and inventory must be arrays.");
  }
  if (!Number.isFinite(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    throw new RangeError("Discount must be between zero and one hundred.");
  }
  const stockBySku = new Map(inventory.map(entry => [entry.sku, entry]));
  const quantities = new Map();
  let subtotal = 0;
  for (const item of items) {
    const product = stockBySku.get(item.sku);
    if (!product || !Number.isSafeInteger(item.quantity) || item.quantity < 1) {
      throw new RangeError("Invalid basket item.");
    }
    const quantity = (quantities.get(item.sku) ?? 0) + item.quantity;
    if (quantity > product.available) {
      throw new RangeError("Not enough stock.");
    }
    quantities.set(item.sku, quantity);
    subtotal += item.quantity * product.priceCents;
  }
  const total = subtotal - Math.round(subtotal * discountPercent / 100);
  const delivery = total === 0 || total >= 5000 ? 0 : 500;
  const receipt = { totalCents: total + delivery, items: [...quantities] };
  if (customer?.canViewStock === true) {
    receipt.remainingStock = [...quantities].map(([sku, quantity]) => ({
      sku, remaining: stockBySku.get(sku).available - quantity
    }));
  }
  return receipt;
}
